-- 1) Verificar que pgvector este disponible
SELECT * FROM pg_available_extensions WHERE name = 'vector';

-- 2) Habilitar pgvector
CREATE EXTENSION IF NOT EXISTS vector;

-- 3) Crear tabla de chunks
CREATE TABLE IF NOT EXISTS public.cs_knowledge_chunks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  text text,
  metadata jsonb DEFAULT '{}'::jsonb,
  embedding vector(1536),
  created_at timestamptz DEFAULT now()
);

-- 4) Indice HNSW para busqueda por similaridad coseno
CREATE INDEX IF NOT EXISTS cs_knowledge_embedding_idx
  ON public.cs_knowledge_chunks USING hnsw (embedding vector_cosine_ops);

-- 5) Indices secundarios sobre metadata para filtros y deletes rapidos
CREATE INDEX IF NOT EXISTS cs_knowledge_product_idx
  ON public.cs_knowledge_chunks ((metadata->>'product'));

CREATE INDEX IF NOT EXISTS cs_knowledge_source_idx
  ON public.cs_knowledge_chunks ((metadata->>'source_file_id'));

-- 6) Verificacion final
SELECT
  (SELECT extversion FROM pg_extension WHERE extname = 'vector') AS pgvector_version,
  (SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name = 'cs_knowledge_chunks') AS table_exists;

