const cfg = $('Load Sync Config').item.json;
const rootFolderId = String(cfg.root_folder_id || '');
const files = Array.isArray($json.files) ? $json.files : [];
const byId = new Map(files.map((f) => [String(f.id), f]));
const g = $getWorkflowStaticData('global');
const lastSync = g.gdrive_last_sync_at || '1970-01-01T00:00:00.000Z';

function hasRootAncestor(file, seen = new Set()) {
  const id = String(file?.id || '');
  if (!id || seen.has(id)) return false;
  seen.add(id);
  const parents = Array.isArray(file?.parents) ? file.parents : [];
  if (parents.includes(rootFolderId)) return true;
  for (const pid of parents) {
    if (pid === rootFolderId) return true;
    const p = byId.get(String(pid));
    if (p && hasRootAncestor(p, seen)) return true;
  }
  return false;
}

const allowedMime = new Set([
  'text/plain',
  'application/pdf',
  'application/vnd.google-apps.document',
  'application/vnd.google-apps.spreadsheet'
]);

const changed = files
  .filter((f) => !f.trashed)
  .filter((f) => allowedMime.has(String(f.mimeType || '')))
  .filter((f) => hasRootAncestor(f))
  .filter((f) => String(f.modifiedTime || '') > lastSync)
  .map((f) => ({
    ...f,
    root_folder_id: rootFolderId,
    last_sync: lastSync
  }));

return changed.map((f) => ({ json: f }));

const file = $input.first().json;
let downloadUrl = '';
if (file.mimeType === 'application/vnd.google-apps.document') {
  downloadUrl = `https://www.googleapis.com/drive/v3/files/${file.id}/export?mimeType=text/plain`;
} else if (file.mimeType === 'application/vnd.google-apps.spreadsheet') {
  downloadUrl = `https://www.googleapis.com/drive/v3/files/${file.id}/export?mimeType=text/csv`;
} else {
  downloadUrl = `https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`;
}
return [{ json: { ...file, download_url: downloadUrl } }];

const file = $('Build Download URL').item.json;
const raw = $json;
let text = '';
if (typeof raw === 'string') { text = raw; }
else if (raw && typeof raw === 'object') { text = JSON.stringify(raw); }
text = String(text || '').replace(/\u0000/g, '').trim();
if (!text) return [];
const normalized = text.substring(0, 12000);
const tokenCount = Math.ceil(normalized.length / 4);
return [{ json: { file_id: file.id, file_name: file.name, mime_type: file.mimeType, modified_time: file.modifiedTime, web_view_link: file.webViewLink || '', checksum: file.md5Checksum || '', content_text: normalized, token_count: tokenCount, metadata: { source: 'google-drive', source_file_id: file.id, source_name: file.name, product: 'customer-service', root_folder_id: file.root_folder_id, last_sync: file.last_sync } } }];

const source = $('Normalize Content').item.json;
const emb = Array.isArray($json.data) && $json.data[0] ? ($json.data[0].embedding || []) : [];
const embLit = '[' + emb.join(',') + ']';
return [{ json: { ...source, embedding_literal: embLit } }];

const g = $getWorkflowStaticData('global');
g.gdrive_last_sync_at = new Date().toISOString();
return [{ json: { ok: true, synced_at: g.gdrive_last_sync_at } }];
